pub mod client;
pub mod launchd;
pub mod protocol;
pub mod server;

pub use client::*;
pub use launchd::*;
pub use protocol::*;
pub use server::*;

use crate::daemon::protocol::{
    DaemonRequest, DaemonResponse, DaemonStreamMessage, DAEMON_PROTOCOL_VERSION,
};
use crate::remote::server::start_remote_server;
use crate::remote::state::{RemoteGatewayConfig, RemoteGatewayState, RemoteNetworkMode};
use crate::session::{
    clear_session_from_path, load_session_from_path, save_session_to_path,
};
use crate::terminal::{PtyManager, TerminalOutputHub, TerminalService};
use crate::worktree::WorkspaceRegistry;
use portable_pty::CommandBuilder;
use std::fs::{self, OpenOptions};
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::broadcast;

pub fn get_runtime_dir() -> PathBuf {
    let uid = unsafe { libc::getuid() };
    let path = PathBuf::from(format!("/tmp/rorca-{uid}"));
    let _ = fs::create_dir_all(&path);
    if let Ok(metadata) = fs::metadata(&path) {
        let mut permissions = metadata.permissions();
        permissions.set_mode(0o700);
        let _ = fs::set_permissions(&path, permissions);
    }
    path
}

pub fn get_socket_path() -> PathBuf {
    get_runtime_dir().join("daemon.sock")
}

pub fn get_lock_path() -> PathBuf {
    get_runtime_dir().join("daemon.lock")
}

pub fn get_default_session_path() -> PathBuf {
    if let Some(mut base) = dirs_next().or_else(dirs_fallback) {
        base.push("rorca");
        let _ = fs::create_dir_all(&base);
        base.join("session_state.json")
    } else {
        get_runtime_dir().join("session_state.json")
    }
}

fn dirs_next() -> Option<PathBuf> {
    #[cfg(target_os = "macos")]
    {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join("Library/Application Support"))
    }
    #[cfg(not(target_os = "macos"))]
    {
        std::env::var_os("XDG_DATA_HOME")
            .map(PathBuf::from)
            .or_else(|| std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".local/share")))
    }
}

fn dirs_fallback() -> Option<PathBuf> {
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".rorca"))
}

pub struct DaemonServer {
    terminal_service: Arc<TerminalService>,
    workspace_registry: WorkspaceRegistry,
    _remote_state: Arc<RemoteGatewayState>,
}

impl Default for DaemonServer {
    fn default() -> Self {
        Self::new()
    }
}

impl DaemonServer {
    pub fn new() -> Self {
        let pty_manager = Arc::new(PtyManager::new());
        let output_hub = Arc::new(TerminalOutputHub::default());
        let terminal_service = Arc::new(TerminalService::new(
            Arc::clone(&pty_manager),
            Arc::clone(&output_hub),
        ));
        let workspace_registry = WorkspaceRegistry::new();
        let remote_state = Arc::new(RemoteGatewayState::new(
            Arc::clone(&terminal_service),
            workspace_registry.clone(),
        ));

        // Start Axum remote gateway by default in daemon
        *remote_state.config.write() = RemoteGatewayConfig {
            mode: RemoteNetworkMode::LocalNetwork,
            port: 43821,
            allow_control: true,
        };
        let rs_clone = Arc::clone(&remote_state);
        tokio::spawn(async move {
            let _ = start_remote_server(rs_clone).await;
        });

        Self {
            terminal_service,
            workspace_registry,
            _remote_state: remote_state,
        }
    }

    pub async fn run_server(self: Arc<Self>) -> Result<(), String> {
        let socket_path = get_socket_path();
        let lock_path = get_lock_path();

        // Flock lock for atomic bind & stale socket recovery
        let lock_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&lock_path)
            .map_err(|e| format!("Failed to open lock file: {e}"))?;

        unsafe {
            use std::os::unix::io::AsRawFd;
            let fd = lock_file.as_raw_fd();
            if libc::flock(fd, libc::LOCK_EX | libc::LOCK_NB) != 0 {
                return Err("Another daemon instance is already holding the lock.".into());
            }
        }

        // Clean up stale socket if any
        if socket_path.exists() {
            let _ = fs::remove_file(&socket_path);
        }

        let listener = UnixListener::bind(&socket_path)
            .map_err(|e| format!("Failed to bind UDS socket at {}: {e}", socket_path.display()))?;

        // Ensure 0600 mode
        if let Ok(metadata) = fs::metadata(&socket_path) {
            let mut permissions = metadata.permissions();
            permissions.set_mode(0o600);
            let _ = fs::set_permissions(&socket_path, permissions);
        }

        tracing::info!("rorca daemon listening on {}", socket_path.display());

        loop {
            match listener.accept().await {
                Ok((stream, _)) => {
                    let server = Arc::clone(&self);
                    tokio::spawn(async move {
                        server.handle_client(stream).await;
                    });
                }
                Err(e) => {
                    tracing::error!("Daemon accept error: {e}");
                    break;
                }
            }
        }

        Ok(())
    }

    async fn handle_client(self: Arc<Self>, stream: UnixStream) {
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);
        let mut line = String::new();

        while let Ok(n) = reader.read_line(&mut line).await {
            if n == 0 {
                break;
            }
            let req: Result<DaemonRequest, _> = serde_json::from_str(line.trim());
            line.clear();

            let resp = match req {
                Ok(DaemonRequest::Handshake { version }) => {
                    if version != DAEMON_PROTOCOL_VERSION {
                        DaemonResponse::Error {
                            message: format!(
                                "Protocol version mismatch: expected {DAEMON_PROTOCOL_VERSION}, got {version}"
                            ),
                        }
                    } else {
                        DaemonResponse::HandshakeOk {
                            version: DAEMON_PROTOCOL_VERSION,
                            pid: std::process::id(),
                        }
                    }
                }
                Ok(DaemonRequest::Ping) => DaemonResponse::Pong,
                Ok(DaemonRequest::Spawn {
                    workspace_id,
                    worktree,
                    cols,
                    rows,
                }) => {
                    let res = self.handle_spawn(&workspace_id, worktree, cols, rows).await;
                    match res {
                        Ok(session_id) => DaemonResponse::SpawnOk { session_id },
                        Err(e) => DaemonResponse::Error { message: e },
                    }
                }
                Ok(DaemonRequest::Write { session_id, data }) => {
                    match self.terminal_service.write_input(&session_id, &data) {
                        Ok(()) => DaemonResponse::WriteOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Resize {
                    session_id,
                    cols,
                    rows,
                }) => match self.terminal_service.resize(&session_id, cols, rows) {
                    Ok(()) => DaemonResponse::ResizeOk,
                    Err(e) => DaemonResponse::Error {
                        message: e.to_string(),
                    },
                },
                Ok(DaemonRequest::Signal { session_id, signal }) => {
                    match self.terminal_service.signal(&session_id, signal) {
                        Ok(()) => DaemonResponse::SignalOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Close { session_id }) => {
                    match self.terminal_service.close_session(&session_id).await {
                        Ok(()) => DaemonResponse::CloseOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::ListSessions) => {
                    let sessions = self.terminal_service.list_sessions();
                    DaemonResponse::ListSessionsOk { sessions }
                }
                Ok(DaemonRequest::Attach { session_id }) => {
                    match self.terminal_service.attach(&session_id) {
                        Ok((history, rx)) => {
                            // Stream live PTY output as stream messages
                            let session_id_clone = session_id.clone();
                            let hub = Arc::clone(self.terminal_service.output_hub());
                            let mut write_clone = write_half; // will be handled
                            // Send initial attach ok
                            let resp = DaemonResponse::AttachOk { history };
                            let mut resp_json = serde_json::to_string(&resp).unwrap();
                            resp_json.push('\n');
                            let _ = write_clone.write_all(resp_json.as_bytes()).await;

                            // Pump output
                            Self::pump_stream(session_id_clone, rx, hub, write_clone).await;
                            return;
                        }
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::SaveSession { session }) => {
                    let path = get_default_session_path();
                    match save_session_to_path(&path, &session) {
                        Ok(()) => DaemonResponse::SaveSessionOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::LoadSession) => {
                    let path = get_default_session_path();
                    match load_session_from_path(&path) {
                        Ok(session) => DaemonResponse::LoadSessionOk { session },
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::ClearSession) => {
                    let path = get_default_session_path();
                    match clear_session_from_path(&path) {
                        Ok(()) => DaemonResponse::ClearSessionOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Shutdown) => {
                    std::process::exit(0);
                }
                Err(e) => DaemonResponse::Error {
                    message: format!("Malformed request: {e}"),
                },
            };

            let mut resp_json = serde_json::to_string(&resp).unwrap();
            resp_json.push('\n');
            if write_half.write_all(resp_json.as_bytes()).await.is_err() {
                break;
            }
        }
    }

    async fn handle_spawn(
        &self,
        workspace_id: &str,
        worktree: Option<crate::worktree::WorktreeIdentity>,
        cols: u16,
        rows: u16,
    ) -> Result<String, String> {
        let (mgr, cwd) = self
            .workspace_registry
            .resolve_terminal_target(workspace_id, worktree.as_ref())
            .map_err(|e| e.to_string())?;

        let mut cmd = CommandBuilder::new_default_prog();
        cmd.cwd(&cwd);

        let (session_id, _) = self
            .terminal_service
            .spawn_in_worktree(cmd, cols, rows, &mgr, &cwd)
            .map_err(|e| e.to_string())?;

        Ok(session_id)
    }

    async fn pump_stream(
        session_id: String,
        mut rx: broadcast::Receiver<Vec<u8>>,
        hub: Arc<TerminalOutputHub>,
        mut writer: tokio::net::unix::OwnedWriteHalf,
    ) {
        loop {
            match rx.recv().await {
                Ok(data) => {
                    let msg = DaemonStreamMessage::Output {
                        session_id: session_id.clone(),
                        data,
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    if writer.write_all(json.as_bytes()).await.is_err() {
                        break;
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => {
                    // Resync with ringbuffer history snapshot
                    if let Some((history, new_rx)) = hub.subscribe(&session_id) {
                        rx = new_rx;
                        let msg = DaemonStreamMessage::Lagged {
                            session_id: session_id.clone(),
                            history,
                        };
                        let mut json = serde_json::to_string(&msg).unwrap();
                        json.push('\n');
                        if writer.write_all(json.as_bytes()).await.is_err() {
                            break;
                        }
                    }
                }
                Err(broadcast::error::RecvError::Closed) => {
                    let msg = DaemonStreamMessage::Exit {
                        session_id: session_id.clone(),
                        exit_code: None,
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    let _ = writer.write_all(json.as_bytes()).await;
                    break;
                }
            }
        }
    }
}

use crate::daemon::protocol::{
    DaemonRequest, DaemonResponse, DAEMON_PROTOCOL_VERSION,
};
use crate::daemon::server::{get_socket_path, DaemonServer};
use crate::ipc::{IpcError, IpcErrorCode};
use crate::session::PersistedWorkspaceSession;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::UnixStream;

#[derive(Clone)]
pub struct DaemonClient {
    // In dev or embedded mode, if daemon is not run standalone, we can either connect to UDS or fallback to direct DaemonServer
    direct_server: Arc<DaemonServer>,
}

impl DaemonClient {
    pub fn new(direct_server: Arc<DaemonServer>) -> Self {
        Self { direct_server }
    }

    async fn connect_or_spawn(&self) -> Result<UnixStream, IpcError> {
        let socket_path = get_socket_path();

        for _ in 0..10 {
            if socket_path.exists() {
                if let Ok(stream) = UnixStream::connect(&socket_path).await {
                    return Ok(stream);
                }
            }
            // Auto spawn daemon in background task
            let server_clone = Arc::clone(&self.direct_server);
            tokio::spawn(async move {
                let _ = server_clone.run_server().await;
            });
            tokio::time::sleep(Duration::from_millis(50)).await;
        }

        UnixStream::connect(&socket_path).await.map_err(|e| {
            IpcError::new(
                IpcErrorCode::InternalError,
                format!("Failed to connect to Ferryx daemon: {e}"),
            )
        })
    }

    pub async fn send_request(&self, req: DaemonRequest) -> Result<DaemonResponse, IpcError> {
        let stream = self.connect_or_spawn().await?;
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);

        // Perform handshake first
        let handshake = DaemonRequest::Handshake {
            version: DAEMON_PROTOCOL_VERSION,
        };
        let mut json = serde_json::to_string(&handshake).unwrap();
        json.push('\n');
        write_half.write_all(json.as_bytes()).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Handshake write failed: {e}"))
        })?;

        let mut line = String::new();
        reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Handshake read failed: {e}"))
        })?;
        let hs_resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(IpcErrorCode::ParseError, format!("Handshake parse failed: {e}"))
        })?;

        if let DaemonResponse::Error { message } = hs_resp {
            return Err(IpcError::new(IpcErrorCode::InternalError, message));
        }

        // Send actual request
        line.clear();
        let mut req_json = serde_json::to_string(&req).unwrap();
        req_json.push('\n');
        write_half.write_all(req_json.as_bytes()).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Request write failed: {e}"))
        })?;

        reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Response read failed: {e}"))
        })?;

        let resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(IpcErrorCode::ParseError, format!("Response parse failed: {e}"))
        })?;

        Ok(resp)
    }

    pub async fn spawn_terminal(
        &self,
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cols: u16,
        rows: u16,
    ) -> Result<String, IpcError> {
        let resp = self
            .send_request(DaemonRequest::Spawn {
                workspace_id,
                worktree,
                cols,
                rows,
            })
            .await?;

        match resp {
            DaemonResponse::SpawnOk { session_id } => Ok(session_id),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn write_terminal(&self, session_id: String, data: Vec<u8>) -> Result<(), IpcError> {
        let resp = self
            .send_request(DaemonRequest::Write { session_id, data })
            .await?;

        match resp {
            DaemonResponse::WriteOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn resize_terminal(&self, session_id: String, cols: u16, rows: u16) -> Result<(), IpcError> {
        let resp = self
            .send_request(DaemonRequest::Resize {
                session_id,
                cols,
                rows,
            })
            .await?;

        match resp {
            DaemonResponse::ResizeOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn signal_terminal(&self, session_id: String, signal: TerminalSignal) -> Result<(), IpcError> {
        let resp = self
            .send_request(DaemonRequest::Signal { session_id, signal })
            .await?;

        match resp {
            DaemonResponse::SignalOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn close_terminal(&self, session_id: String) -> Result<(), IpcError> {
        let resp = self.send_request(DaemonRequest::Close { session_id }).await?;

        match resp {
            DaemonResponse::CloseOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn list_sessions(&self) -> Result<Vec<String>, IpcError> {
        let resp = self.send_request(DaemonRequest::ListSessions).await?;

        match resp {
            DaemonResponse::ListSessionsOk { sessions } => Ok(sessions),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn save_session(&self, session: PersistedWorkspaceSession) -> Result<(), IpcError> {
        let resp = self.send_request(DaemonRequest::SaveSession { session }).await?;

        match resp {
            DaemonResponse::SaveSessionOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn load_session(&self) -> Result<Option<PersistedWorkspaceSession>, IpcError> {
        let resp = self.send_request(DaemonRequest::LoadSession).await?;

        match resp {
            DaemonResponse::LoadSessionOk { session } => Ok(session),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }

    pub async fn clear_session(&self) -> Result<(), IpcError> {
        let resp = self.send_request(DaemonRequest::ClearSession).await?;

        match resp {
            DaemonResponse::ClearSessionOk => Ok(()),
            DaemonResponse::Error { message } => Err(IpcError::new(IpcErrorCode::InternalError, message)),
            _ => Err(IpcError::new(IpcErrorCode::InternalError, "Unexpected daemon response")),
        }
    }
}

use crate::session::PersistedWorkspaceSession;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use serde::{Deserialize, Serialize};

pub const DAEMON_PROTOCOL_VERSION: u32 = 1;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonRequest {
    Handshake { version: u32 },
    Ping,
    Spawn {
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cols: u16,
        rows: u16,
    },
    Write {
        session_id: String,
        data: Vec<u8>,
    },
    Resize {
        session_id: String,
        cols: u16,
        rows: u16,
    },
    Signal {
        session_id: String,
        signal: TerminalSignal,
    },
    Close {
        session_id: String,
    },
    ListSessions,
    Attach {
        session_id: String,
    },
    SaveSession {
        session: PersistedWorkspaceSession,
    },
    LoadSession,
    ClearSession,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonResponse {
    HandshakeOk { version: u32, pid: u32 },
    Pong,
    SpawnOk { session_id: String },
    WriteOk,
    ResizeOk,
    SignalOk,
    CloseOk,
    ListSessionsOk { sessions: Vec<String> },
    AttachOk { history: Vec<u8> },
    SaveSessionOk,
    LoadSessionOk { session: Option<PersistedWorkspaceSession> },
    ClearSessionOk,
    Error { message: String },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonStreamMessage {
    Output { session_id: String, data: Vec<u8> },
    Lagged { session_id: String, history: Vec<u8> },
    Exit { session_id: String, exit_code: Option<i32> },
}

use std::fs;
use std::path::PathBuf;
use std::process::Command;

const PLIST_LABEL: &str = "com.rorca.daemon";

pub fn get_launchd_plist_path() -> Option<PathBuf> {
    std::env::var_os("HOME").map(|h| {
        PathBuf::from(h)
            .join("Library/LaunchAgents")
            .join(format!("{PLIST_LABEL}.plist"))
    })
}

pub fn generate_launchd_plist(executable_path: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>{PLIST_LABEL}</string>
    <key>ProgramArguments</key>
    <array>
        <string>{executable_path}</string>
        <string>--daemon</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <key>StandardOutPath</key>
    <string>/tmp/rorca-daemon.log</string>
    <key>StandardErrorPath</key>
    <string>/tmp/rorca-daemon.err</string>
</dict>
</plist>
"#
    )
}

pub fn install_launchd_agent() -> Result<PathBuf, String> {
    let plist_path = get_launchd_plist_path().ok_or("Cannot determine HOME directory")?;
    if let Some(parent) = plist_path.parent() {
        let _ = fs::create_dir_all(parent);
    }

    let current_exe = std::env::current_exe().map_err(|e| format!("Failed to get current exe path: {e}"))?;
    let content = generate_launchd_plist(&current_exe.to_string_lossy());
    fs::write(&plist_path, content).map_err(|e| format!("Failed to write plist: {e}"))?;

    let _ = Command::new("launchctl")
        .args(["load", "-w", &plist_path.to_string_lossy()])
        .output();

    Ok(plist_path)
}

pub fn uninstall_launchd_agent() -> Result<(), String> {
    let plist_path = get_launchd_plist_path().ok_or("Cannot determine HOME directory")?;
    if plist_path.exists() {
        let _ = Command::new("launchctl")
            .args(["unload", "-w", &plist_path.to_string_lossy()])
            .output();
        let _ = fs::remove_file(&plist_path);
    }
    Ok(())
}

use crate::ipc::{IpcError, IpcErrorCode};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
